1	//! Gemma subid router — event-driven multi-store projection of mutations.
2	//!
3	//! The router is the Law Firm's runtime. It subscribes to the `MutationEngine`
4	//! broadcast channel and, for every `StateChange`, classifies the subid and
5	//! materializes the change into the right store(s):
6	//!
7	//! - **Reggie O.P.A.** — `CozoGraphShuttle::evaluate_mutation` is consulted
8	//!   before any structural projection; a `Deny` verdict writes a deny
9	//!   `audit_event` and stops.
10	//! - **Audit trail** — every change (allowed or denied) is appended to the
11	//!   embedded cozo `audit_event` relation (`append_audit_event`).
12	//! - **Embedding** — only content-bearing categories (`obs`/`exp`) with
13	//!   non-empty text are embedded via Voyage and upserted into Qdrant.
14	//!
15	//! Cozo is the **embedded** `op-cozo-store` graph store (in-process, reached
16	//! over gRPC by external clients via the bridge); there is no cozoserver HTTP
17	//! client here. Qdrant is reached through the existing `QdrantSemanticShuttle`
18	//! gRPC client. The router never polls a store or a file — it is purely
19	//! event-driven off the broadcast channel.
20	
21	use std::sync::Arc;
22	
23	use op_cognitive_mcp::QdrantSemanticShuttle;
24	use op_cozo_store::CozoGraphShuttle;
25	use op_identity::{SubidCategory, SubidTaxonomy};
26	use tokio::sync::broadcast;
27	use tracing::{debug, info, warn};
28	
29	use crate::mutation_engine::{ChangeType, StateChange};
30	
31	/// Long-lived projection consumer of `MutationEngine` state changes.
32	pub struct SubidRouter {
33	    rx: broadcast::Receiver<StateChange>,
34	    cozo: Arc<CozoGraphShuttle>,
35	    qdrant: Option<Arc<QdrantSemanticShuttle>>,
36	}
37	
38	impl SubidRouter {
39	    pub fn new(
40	        rx: broadcast::Receiver<StateChange>,
41	        cozo: Arc<CozoGraphShuttle>,
42	        qdrant: Option<Arc<QdrantSemanticShuttle>>,
43	    ) -> Self {
44	        Self { rx, cozo, qdrant }
45	    }
46	
47	    /// Classify a change into its subid category and canonical subid string.
48	    ///
49	    /// Prefers an explicit subid carried in `tags_touched`; otherwise derives a
50	    /// best-effort subid from the change type (`Signal` → `evt`, `SchemaMigration`
51	    /// → `sch`, everything else → `mut`).
52	    fn classify(change: &StateChange) -> (SubidCategory, String) {
53	        for tag in &change.tags_touched {
54	            if let Ok(taxonomy) = SubidTaxonomy::parse(tag) {
55	                return (taxonomy.category, taxonomy.canonical());
56	            }
57	        }
58	
59	        let category = match change.change_type {
60	            ChangeType::Signal => SubidCategory::Evt,
61	            ChangeType::SchemaMigration => SubidCategory::Sch,
62	            _ => SubidCategory::Mut,
63	        };
64	        let subject = sanitize_segment(&change.plugin_id);
65	        let verb = operation_verb(change);
66	        (
67	            category,
68	            format!("{}.software.{}.{}@v1", category.as_str(), subject, verb),
69	        )
70	    }
71	
72	    /// Content-bearing gate (FR-F1): only `obs`/`exp` subids with non-empty text
73	    /// are eligible for embedding. Structural categories are never embedded.
74	    pub fn is_content_bearing(category: SubidCategory, payload_text: &str) -> bool {
75	        matches!(category, SubidCategory::Obs | SubidCategory::Exp)
76	            && !payload_text.trim().is_empty()
77	    }
78	
79	    async fn route(&self, change: StateChange) {
80	        let (category, subid) = Self::classify(&change);
81	        let operation = operation_verb(&change);
82	
83	        // evt.* is chain-only: the EventChain already recorded it in
84	        // MutationEngine; the router just confirms receipt.
85	        if category == SubidCategory::Evt {
86	            debug!(subid = %subid, plugin = %change.plugin_id, "subid-router: evt confirmed (chain-only)");
87	            return;
88	        }
89	
90	        // Reggie O.P.A. — compliance gate before any projection.
91	        let verdict = self.cozo.evaluate_mutation(&change.plugin_id, &operation);
92	        if !verdict.allow {
93	            if let Err(error) = self.cozo.append_audit_event(
94	                &change.event_hash,
95	                &subid,
96	                &change.plugin_id,
97	                &operation,
98	                &change.actor_id,
99	                false,
100	                &verdict.reason,
101	                "",
102	            ) {
103	                warn!(%error, subid = %subid, "subid-router: failed to write deny audit_event");
104	            }
105	            info!(subid = %subid, plugin = %change.plugin_id, reason = %verdict.reason, "subid-router: mutation denied by compliance gate");
106	            return;
107	        }
108	
109	        // Append-only audit trail for every allowed change.
110	        if let Err(error) = self.cozo.append_audit_event(
111	            &change.event_hash,
112	            &subid,
113	            &change.plugin_id,
114	            &operation,
115	            &change.actor_id,
116	            true,
117	            "no deny rule matched",
118	            "",
119	        ) {
120	            warn!(%error, subid = %subid, "subid-router: failed to write audit_event");
121	        }
122	
123	        // Content-bearing projection to Qdrant (obs/exp + non-empty text only).
124	        let text = payload_text(&change);
125	        if Self::is_content_bearing(category, &text) {
126	            if let Some(qdrant) = &self.qdrant {
127	                let mut payload = serde_json::Map::new();
128	                payload.insert(
129	                    "subid".to_string(),
130	                    serde_json::Value::String(subid.clone()),
131	                );
132	                payload.insert(
133	                    "plugin_id".to_string(),
134	                    serde_json::Value::String(change.plugin_id.clone()),
135	                );
136	                payload.insert(
137	                    "object_path".to_string(),
138	                    serde_json::Value::String(change.object_path.clone()),
139	                );
140	                payload.insert(
141	                    "actor_id".to_string(),
142	                    serde_json::Value::String(change.actor_id.clone()),
143	                );
144	                payload.insert(
145	                    "event_hash".to_string(),
146	                    serde_json::Value::String(change.event_hash.clone()),
147	                );
148	                if let Err(error) = qdrant.embed_and_upsert(&text, payload).await {
149	                    warn!(%error, subid = %subid, "subid-router: embed/upsert to qdrant failed");
150	                }
151	            } else {
152	                debug!(subid = %subid, "subid-router: content-bearing change but no qdrant shuttle attached");
153	            }
154	        }
155	    }
156	
157	    /// Run the router until the broadcast channel closes. Lagged events are
158	    /// logged and skipped; a closed channel exits cleanly (no panic).
159	    pub async fn run(mut self) {
160	        info!("subid-router: started");
161	        loop {
162	            match self.rx.recv().await {
163	                Ok(change) => self.route(change).await,
164	                Err(broadcast::error::RecvError::Lagged(n)) => {
165	                    warn!(skipped = n, "subid-router: lagged, skipped changes");
166	                }
167	                Err(broadcast::error::RecvError::Closed) => {
168	                    info!("subid-router: broadcast channel closed, exiting");
169	                    break;
170	                }
171	            }
172	        }
173	    }
174	}
175	
176	/// Operation verb for audit/compliance keyed off the change type.
177	fn operation_verb(change: &StateChange) -> String {
178	    match change.change_type {
179	        ChangeType::PropertySet => "set".to_string(),
180	        ChangeType::PropertyDelete => "delete".to_string(),
181	        ChangeType::MethodCall => change
182	            .member_name
183	            .clone()
184	            .unwrap_or_else(|| "call".to_string()),
185	        ChangeType::Signal => "signal".to_string(),
186	        ChangeType::ObjectAdded => "add".to_string(),
187	        ChangeType::ObjectRemoved => "remove".to_string(),
188	        ChangeType::SchemaMigration => "migrate".to_string(),
189	    }
190	}
191	
192	/// Extract embeddable text from the change's new value.
193	fn payload_text(change: &StateChange) -> String {
194	    use simd_json::prelude::ValueAsScalar;
195	    if let Some(s) = change.new_value.as_str() {
196	        return s.to_string();
197	    }
198	    simd_json::to_string(&change.new_value).unwrap_or_default()
199	}
200	
201	/// Reduce an identifier to lowercase ascii/digit/hyphen segments for subid use.
202	fn sanitize_segment(raw: &str) -> String {
203	    let cleaned: String = raw
204	        .chars()
205	        .map(|c| {
206	            if c.is_ascii_alphanumeric() {
207	                c.to_ascii_lowercase()
208	            } else {
209	                '-'
210	            }
211	        })
212	        .collect();
213	    let trimmed = cleaned.trim_matches('-').to_string();
214	    if trimmed.is_empty() {
215	        "unknown".to_string()
216	    } else {
217	        trimmed
218	    }
219	}
