221	#[cfg(test)]
222	mod tests {
223	    use super::*;
224	    use chrono::Utc;
225	
226	    fn change(
227	        change_type: ChangeType,
228	        tags: Vec<String>,
229	        new_value: simd_json::OwnedValue,
