//! Gemma subid router — event-driven multi-store projection of mutations.
//!
//! The router is the Law Firm's runtime. It subscribes to the `MutationEngine`
//! broadcast channel and, for every `StateChange`, classifies the subid and
//! materializes the change into the right store(s):
//!
//! - **Reggie O.P.A.** — `CozoGraphShuttle::evaluate_mutation` is consulted
//!   before any structural projection; a `Deny` verdict writes a deny
//!   `audit_event` and stops.
//! - **Audit trail** — every change (allowed or denied) is appended to the
//!   embedded cozo `audit_event` relation (`append_audit_event`).
//! - **Embedding** — only content-bearing categories (`obs`/`exp`) with
//!   non-empty text are embedded via Voyage and upserted into Qdrant.
//!
//! Cozo is the **embedded** `op-cozo-store` graph store (in-process, reached
//! over gRPC by external clients via the bridge); there is no cozoserver HTTP
//! client here. Qdrant is reached through the existing `QdrantSemanticShuttle`
//! gRPC client. The router never polls a store or a file — it is purely
//! event-driven off the broadcast channel.

use std::sync::Arc;

use op_cognitive_mcp::QdrantSemanticShuttle;
use op_cozo_store::CozoGraphShuttle;
use op_identity::{SubidCategory, SubidTaxonomy};
use tokio::sync::broadcast;
use tracing::{debug, info, warn};

use crate::mutation_engine::{ChangeType, StateChange};

/// Long-lived projection consumer of `MutationEngine` state changes.
pub struct SubidRouter {
    rx: broadcast::Receiver<StateChange>,
    cozo: Arc<CozoGraphShuttle>,
    qdrant: Option<Arc<QdrantSemanticShuttle>>,
}

impl SubidRouter {
    pub fn new(
        rx: broadcast::Receiver<StateChange>,
        cozo: Arc<CozoGraphShuttle>,
        qdrant: Option<Arc<QdrantSemanticShuttle>>,
    ) -> Self {
        Self { rx, cozo, qdrant }
    }

    /// Classify a change into its subid category and canonical subid string.
    ///
    /// Prefers an explicit subid carried in `tags_touched`; otherwise derives a
    /// best-effort subid from the change type (`Signal` → `evt`, `SchemaMigration`
    /// → `sch`, everything else → `mut`).
    fn classify(change: &StateChange) -> (SubidCategory, String) {
        for tag in &change.tags_touched {
            if let Ok(taxonomy) = SubidTaxonomy::parse(tag) {
                return (taxonomy.category, taxonomy.canonical());
            }
        }

        let category = match change.change_type {
            ChangeType::Signal => SubidCategory::Evt,
            ChangeType::SchemaMigration => SubidCategory::Sch,
            _ => SubidCategory::Mut,
        };
        let subject = sanitize_segment(&change.plugin_id);
        let verb = operation_verb(change);
        (
            category,
            format!("{}.software.{}.{}@v1", category.as_str(), subject, verb),
        )
    }

    /// Content-bearing gate (FR-F1): only `obs`/`exp` subids with non-empty text
    /// are eligible for embedding. Structural categories are never embedded.
    pub fn is_content_bearing(category: SubidCategory, payload_text: &str) -> bool {
        matches!(category, SubidCategory::Obs | SubidCategory::Exp)
            && !payload_text.trim().is_empty()
    }

    async fn route(&self, change: StateChange) {
        let (category, subid) = Self::classify(&change);
        let operation = operation_verb(&change);

        // evt.* is chain-only: the EventChain already recorded it in
        // MutationEngine; the router just confirms receipt.
        if category == SubidCategory::Evt {
            debug!(subid = %subid, plugin = %change.plugin_id, "subid-router: evt confirmed (chain-only)");
            return;
        }

        // Reggie O.P.A. — compliance gate before any projection.
        let verdict = self.cozo.evaluate_mutation(&change.plugin_id, &operation);
        if !verdict.allow {
            if let Err(error) = self.cozo.append_audit_event(
                &change.event_hash,
                &subid,
                &change.plugin_id,
                &operation,
                &change.actor_id,
                false,
                &verdict.reason,
                "",
            ) {
                warn!(%error, subid = %subid, "subid-router: failed to write deny audit_event");
            }
            info!(subid = %subid, plugin = %change.plugin_id, reason = %verdict.reason, "subid-router: mutation denied by compliance gate");
            return;
        }

        // Append-only audit trail for every allowed change.
        if let Err(error) = self.cozo.append_audit_event(
            &change.event_hash,
            &subid,
            &change.plugin_id,
            &operation,
            &change.actor_id,
            true,
            "no deny rule matched",
            "",
        ) {
            warn!(%error, subid = %subid, "subid-router: failed to write audit_event");
        }

        // Content-bearing projection to Qdrant (obs/exp + non-empty text only).
        let text = payload_text(&change);
        if Self::is_content_bearing(category, &text) {
            if let Some(qdrant) = &self.qdrant {
                let mut payload = serde_json::Map::new();
                payload.insert(
                    "subid".to_string(),
                    serde_json::Value::String(subid.clone()),
                );
                payload.insert(
                    "plugin_id".to_string(),
                    serde_json::Value::String(change.plugin_id.clone()),
                );
                payload.insert(
                    "object_path".to_string(),
                    serde_json::Value::String(change.object_path.clone()),
                );
                payload.insert(
                    "actor_id".to_string(),
                    serde_json::Value::String(change.actor_id.clone()),
                );
                payload.insert(
                    "event_hash".to_string(),
                    serde_json::Value::String(change.event_hash.clone()),
                );
                if let Err(error) = qdrant.embed_and_upsert(&text, payload).await {
                    warn!(%error, subid = %subid, "subid-router: embed/upsert to qdrant failed");
                }
            } else {
                debug!(subid = %subid, "subid-router: content-bearing change but no qdrant shuttle attached");
            }
        }
    }

    /// Run the router until the broadcast channel closes. Lagged events are
    /// logged and skipped; a closed channel exits cleanly (no panic).
    pub async fn run(mut self) {
        info!("subid-router: started");
        loop {
            match self.rx.recv().await {
                Ok(change) => self.route(change).await,
                Err(broadcast::error::RecvError::Lagged(n)) => {
                    warn!(skipped = n, "subid-router: lagged, skipped changes");
                }
                Err(broadcast::error::RecvError::Closed) => {
                    info!("subid-router: broadcast channel closed, exiting");
                    break;
                }
            }
        }
    }
}

/// Operation verb for audit/compliance keyed off the change type.
fn operation_verb(change: &StateChange) -> String {
    match change.change_type {
        ChangeType::PropertySet => "set".to_string(),
        ChangeType::PropertyDelete => "delete".to_string(),
        ChangeType::MethodCall => change
            .member_name
            .clone()
            .unwrap_or_else(|| "call".to_string()),
        ChangeType::Signal => "signal".to_string(),
        ChangeType::ObjectAdded => "add".to_string(),
        ChangeType::ObjectRemoved => "remove".to_string(),
        ChangeType::SchemaMigration => "migrate".to_string(),
    }
}

/// Extract embeddable text from the change's new value.
fn payload_text(change: &StateChange) -> String {
    use simd_json::prelude::ValueAsScalar;
    if let Some(s) = change.new_value.as_str() {
        return s.to_string();
    }
    simd_json::to_string(&change.new_value).unwrap_or_default()
}

/// Reduce an identifier to lowercase ascii/digit/hyphen segments for subid use.
fn sanitize_segment(raw: &str) -> String {
    let cleaned: String = raw
        .chars()
        .map(|c| {
            if c.is_ascii_alphanumeric() {
                c.to_ascii_lowercase()
            } else {
                '-'
            }
        })
        .collect();
    let trimmed = cleaned.trim_matches('-').to_string();
    if trimmed.is_empty() {
        "unknown".to_string()
    } else {
        trimmed
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use chrono::Utc;

    fn change(
        change_type: ChangeType,
        tags: Vec<String>,
        new_value: simd_json::OwnedValue,
    ) -> StateChange {
        StateChange {
            change_id: "c1".to_string(),
            event_id: 1,
            plugin_id: "rocksdb".to_string(),
            object_path: "/org/opdbus/v1/plugins/rocksdb".to_string(),
            change_type,
            member_name: None,
            old_value: None,
            new_value,
            tags_touched: tags,
            event_hash: "hash-1".to_string(),
            timestamp: Utc::now(),
            actor_id: "wgpub".to_string(),
            source: crate::mutation_engine::ChangeSource::Grpc,
        }
    }

    #[test]
    fn classifies_explicit_subid_from_tags() {
        let c = change(
            ChangeType::PropertySet,
            vec!["obs.software.rocksdb.stats@v1".to_string()],
            simd_json::json!("free text"),
        );
        let (category, subid) = SubidRouter::classify(&c);
        assert_eq!(category, SubidCategory::Obs);
        assert_eq!(subid, "obs.software.rocksdb.stats@v1");
    }

    #[test]
    fn derives_mut_for_property_set_without_subid_tag() {
        let c = change(
            ChangeType::PropertySet,
            vec!["state".to_string()],
            simd_json::json!({}),
        );
        let (category, subid) = SubidRouter::classify(&c);
        assert_eq!(category, SubidCategory::Mut);
        assert_eq!(subid, "mut.software.rocksdb.set@v1");
    }

    #[test]
    fn derives_evt_for_signal() {
        let c = change(ChangeType::Signal, vec![], simd_json::json!(null));
        let (category, _) = SubidRouter::classify(&c);
        assert_eq!(category, SubidCategory::Evt);
    }

    #[test]
    fn content_bearing_only_for_obs_exp_with_text() {
        assert!(SubidRouter::is_content_bearing(SubidCategory::Obs, "hello"));
        assert!(SubidRouter::is_content_bearing(SubidCategory::Exp, "hello"));
        assert!(!SubidRouter::is_content_bearing(SubidCategory::Obs, "   "));
        assert!(!SubidRouter::is_content_bearing(
            SubidCategory::Mut,
            "hello"
        ));
        assert!(!SubidRouter::is_content_bearing(
            SubidCategory::Src,
            "hello"
        ));
    }

    #[tokio::test]
    async fn mut_change_writes_allow_audit_event_and_no_embedding() {
        let cozo = Arc::new(CozoGraphShuttle::new_in_memory().expect("in-memory cozo"));
        let (tx, rx) = broadcast::channel(8);
        let router = SubidRouter::new(rx, cozo.clone(), None);

        tx.send(change(
            ChangeType::PropertySet,
            vec!["state".to_string()],
            simd_json::json!({"k": "v"}),
        ))
        .expect("send");
        drop(tx);

        router.run().await;

        let rows = cozo
            .run_query(
                "?[event_id, verdict] := *audit_event[event_id, _, _, _, _, verdict, _, _, _]",
                None,
            )
            .expect("query audit_event");
        let arr = rows.as_array().expect("array");
        assert_eq!(arr.len(), 1, "exactly one audit_event row");
        assert_eq!(arr[0]["verdict"], serde_json::json!("allow"));
    }

    #[tokio::test]
    async fn evt_change_writes_no_audit_event() {
        let cozo = Arc::new(CozoGraphShuttle::new_in_memory().expect("in-memory cozo"));
        let (tx, rx) = broadcast::channel(8);
        let router = SubidRouter::new(rx, cozo.clone(), None);

        tx.send(change(ChangeType::Signal, vec![], simd_json::json!(null)))
            .expect("send");
        drop(tx);

        router.run().await;

        let rows = cozo
            .run_query(
                "?[event_id] := *audit_event[event_id, _, _, _, _, _, _, _, _]",
                None,
            )
            .expect("query audit_event");
        assert_eq!(
            rows.as_array().expect("array").len(),
            0,
            "evt is chain-only"
        );
    }

    #[tokio::test]
    async fn run_exits_cleanly_on_closed_channel() {
        let cozo = Arc::new(CozoGraphShuttle::new_in_memory().expect("in-memory cozo"));
        let (tx, rx) = broadcast::channel::<StateChange>(8);
        let router = SubidRouter::new(rx, cozo, None);
        drop(tx);
        // Should return promptly without panicking.
        router.run().await;
    }
}

