    &self,
    calls: Vec<(&str, Value)>,
) -> Result<Vec<(String, Result<Value>)>> {
    let futures: Vec<_> = calls
        .into_iter()
        .map(|(name, params)| async move {
            let result = self.call_tool(name, params).await;
            (name.to_string(), result)
        })
        .collect();

