1	//! op-mcp-shim — MCP (stdio) ⇄ gRPC bridge driven entirely by server reflection.
2	//!
3	//! Spawned by MCP clients (claude-code, gemini CLI, factory/droid) as a stdio
4	//! server. On tools/list it reflects the target gRPC endpoint and projects
5	//! every unary RPC as an MCP tool (schema derived from the proto descriptors);
6	//! tools/call builds a DynamicMessage from the JSON arguments and invokes the
7	//! method. New RPCs on the server appear as tools with no rebuild here.
8	//!
9	//! Identity: x-ghostbridge-* headers are normally injected in-path by xray.
10	//! For direct connections set GHOSTBRIDGE_FOOTPRINT / GHOSTBRIDGE_TRACE_ID or
11	//! pass --header.
12	
13	mod codec;
14	mod discovery;
15	mod schema;
16	
17	use std::str::FromStr;
18	
19	use clap::Parser;
20	use prost_reflect::{DescriptorPool, DynamicMessage, MethodDescriptor};
21	use serde_json::{json, Value};
22	use tokio::io::{AsyncBufReadExt, BufReader};
23	use tonic::codegen::http::uri::PathAndQuery;
24	use tonic::metadata::{Ascii, MetadataKey, MetadataValue};
25	use tonic::transport::{Channel, ClientTlsConfig, Endpoint};
26	
27	#[derive(Parser)]
28	#[command(version, about = "MCP stdio shim over gRPC reflection")]
