/// Build a lazy gRPC channel from an endpoint string.
///
/// Accepts standard `http(s)://host:port` URIs and — honoring the "No Container
/// NIC/IP, never TCP host:port" rule — a `unix:///path/to.sock` endpoint to dial
/// the backplane over a Unix domain socket (the canonical `container.sock`
/// transport that fronts the grpc-bridge `PluginService` door).
fn build_channel(endpoint: &str) -> anyhow::Result<Channel> {
    if let Some(path) = endpoint
        .strip_prefix("unix://")
        .or_else(|| endpoint.strip_prefix("unix:"))
    {
        let path = std::path::PathBuf::from(path);
        // The HTTP authority below is ignored by the UDS connector, but tonic
        // still requires a syntactically valid URI to carry request settings.
        let channel = Endpoint::try_from("http://[::]:50051")?.connect_with_connector_lazy(
            service_fn(move |_: Uri| {
                let path = path.clone();
                async move { UnixStream::connect(path).await.map(TokioIo::new) }
            }),
        );
        return Ok(channel);
    }

    let mut ep: Endpoint = Channel::from_shared(endpoint.to_string())?;
    if endpoint.starts_with("https://") {
        ep = ep.tls_config(ClientTlsConfig::new().with_native_roots())?;
    }
    Ok(ep.connect_lazy())
}

