/// Decode reflection file bytes into `files`, queuing any not-yet-seen imports
/// onto `pending_deps` so the caller can fetch them by filename.
fn ingest_files(
    raw: Vec<Vec<u8>>,
    files: &mut HashMap<String, FileDescriptorProto>,
    pending_deps: &mut Vec<String>,
) -> anyhow::Result<()> {
    for bytes in raw {
        let fd = FileDescriptorProto::decode(&bytes[..])?;
        for dep in &fd.dependency {
            if !files.contains_key(dep) {
                pending_deps.push(dep.clone());
            }
        }
        files.entry(fd.name().to_string()).or_insert(fd);
    }
    Ok(())
}

