use std::collections::HashMap;

use prost::Message;
use prost_reflect::DescriptorPool;
use prost_types::FileDescriptorProto;
use tonic::transport::Channel;
use tonic_reflection::pb::v1::{
    server_reflection_client::ServerReflectionClient, server_reflection_request::MessageRequest,
    server_reflection_response::MessageResponse, ServerReflectionRequest,
};

pub async fn build_pool(channel: Channel) -> anyhow::Result<DescriptorPool> {
    let mut client = ServerReflectionClient::new(channel);

    let services = match call(&mut client, MessageRequest::ListServices(String::new())).await? {
        MessageResponse::ListServicesResponse(list) => {
            list.service.into_iter().map(|s| s.name).collect::<Vec<_>>()
        }
        other => anyhow::bail!("unexpected reflection response: {other:?}"),
    };

    let mut files: HashMap<String, FileDescriptorProto> = HashMap::new();

    // Seed the pool with the file that declares each service symbol. Track every
    // `import` we encounter so we can resolve the transitive closure below.
    let mut pending_deps: Vec<String> = Vec::new();
    for service in &services {
        if service.starts_with("grpc.reflection") {
            continue;
        }
        let resp = call(
            &mut client,
            MessageRequest::FileContainingSymbol(service.clone()),
        )
        .await?;
        if let MessageResponse::FileDescriptorResponse(fdr) = resp {
            ingest_files(fdr.file_descriptor_proto, &mut files, &mut pending_deps)?;
        }
    }

    // Resolve imported files (`operation.proto`, `mail.proto`, …) that the
    // server returns by filename rather than bundling into the symbol response.
    // Without this the DescriptorPool can never satisfy cross-file dependencies.
    while let Some(dep) = pending_deps.pop() {
        if files.contains_key(&dep) {
            continue;
        }
        let resp = call(&mut client, MessageRequest::FileByFilename(dep.clone())).await?;
        if let MessageResponse::FileDescriptorResponse(fdr) = resp {
            ingest_files(fdr.file_descriptor_proto, &mut files, &mut pending_deps)?;
        }
    }

    // Reflection returns files in arbitrary order; add until dependencies resolve.
    let mut pool = DescriptorPool::new();
    let mut remaining: Vec<FileDescriptorProto> = files.into_values().collect();
    while !remaining.is_empty() {
        let before = remaining.len();
        let mut next = Vec::new();
        for fd in remaining {
            if pool.add_file_descriptor_proto(fd.clone()).is_err() {
                next.push(fd);
            }
        }
        remaining = next;
        if remaining.len() == before {
            anyhow::bail!(
                "unresolvable proto dependencies: {:?}",
                remaining
                    .iter()
                    .map(|f| f.name().to_string())
                    .collect::<Vec<_>>()
            );
        }
    }
    Ok(pool)
}

async fn call(
    client: &mut ServerReflectionClient<Channel>,
    req: MessageRequest,
) -> anyhow::Result<MessageResponse> {
    let request = ServerReflectionRequest {
        host: String::new(),
        message_request: Some(req),
    };
    let mut stream = client
        .server_reflection_info(tokio_stream::once(request))
        .await?
        .into_inner();
    let resp = stream
        .message()
        .await?
        .ok_or_else(|| anyhow::anyhow!("empty reflection response"))?;
    match resp.message_response {
        Some(MessageResponse::ErrorResponse(e)) => {
            anyhow::bail!("reflection error {}: {}", e.error_code, e.error_message)
        }
        Some(m) => Ok(m),
        None => anyhow::bail!("missing reflection payload"),
    }
}
